-- PKG_SYS0014 — 클라우드 현재 상태 점검 (SCM_MGR · 조회 전용 · 변경 없음)
-- VERDICT: PRE=사내 적용 전과 동일 → 해당 파일 적용 / POST=이미 적용 → SKIP / ABSENT=없음 / DIFF=클라우드 본문이 다름 → 전체교체 금지·결과 공유
SET PAGESIZE 200 LINESIZE 300
COLUMN OBJ FORMAT A48
COLUMN VERDICT FORMAT A60

-- [A] 교체 대상 객체
SELECT 'PKG_SYS0014' OBJ, 'PACKAGE' TYP, '10_SPEC.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_SYS0014' AND OBJECT_TYPE = 'PACKAGE') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_SYS0014' AND OBJECT_TYPE = 'PACKAGE') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 49486090810 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 12976279435 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_SYS0014' AND TYPE = 'PACKAGE' AND LINE > 1) H;
SELECT 'PKG_SYS0014' OBJ, 'PACKAGE BODY' TYP, '11_BODY.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_SYS0014' AND OBJECT_TYPE = 'PACKAGE BODY') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_SYS0014' AND OBJECT_TYPE = 'PACKAGE BODY') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 716622798671 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 80403760335 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_SYS0014' AND TYPE = 'PACKAGE BODY' AND LINE > 1) H;

-- [B] DROP 대상 standalone — 멤버 본문 원천. DIFF 면 클라우드에만 있는 수정 → 멤버에 반영 필요(결과 공유)
SELECT 'P_SYS0014_GET_AUTH_LIST_M' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'P_SYS0014_GET_AUTH_LIST_M' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (101139058010, 101139058010) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'P_SYS0014_GET_AUTH_LIST_M' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'P_SYS0014_GET_GROUP_LIST_M' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'P_SYS0014_GET_GROUP_LIST_M' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (50482550345, 50482550345) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'P_SYS0014_GET_GROUP_LIST_M' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'P_SYS0014_GET_USER_BY_GROUP_M' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'P_SYS0014_GET_USER_BY_GROUP_M' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (69771635059, 69771635059) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'P_SYS0014_GET_USER_BY_GROUP_M' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'P_SYS0014_SAVE_GROUP_USER_M' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'P_SYS0014_SAVE_GROUP_USER_M' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (396916469483, 396916469483) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'P_SYS0014_SAVE_GROUP_USER_M' AND TYPE = 'PROCEDURE' AND LINE > 1) H;

-- [C] PKG_SYS0014 BODY 의존 객체 — 행이 나오면 MISSING (컴파일 실패 조건)
SELECT COLUMN_VALUE MISSING FROM TABLE(SYS.ODCIVARCHAR2LIST('SCM_ADM_USER_GR_M', 'SCM_ADM_USER_GR_MPG_M', 'SCM_ADM_USER_GR_UNIT_AUTH_MPG_M', 'SCM_ADM_USER_M', 'SCM_MST_DIVISION', 'SCM_MST_SSO_DEPT_INFO')) WHERE COLUMN_VALUE NOT IN (SELECT OBJECT_NAME FROM USER_OBJECTS);

-- [D] META 현재값 — API_URL 이 standalone 이면 전환 전, PKG.멤버 면 전환 완료
SELECT API_ID, API_URL FROM SCM_ADM_API_M WHERE API_ID IN ('API_SYS0014_GET_AUTH_LIST', 'API_SYS0014_GET_GROUP_LIST', 'API_SYS0014_GET_USER_BY_GROUP', 'API_SYS0014_SAVE_GROUP_USER') ORDER BY API_ID;
SELECT UPPER(PROC_NM) PROC_NM, COUNT(*) CNT FROM SCM_ADM_PROC_M WHERE UPPER(PROC_NM) IN ('P_SYS0014_GET_AUTH_LIST_M', 'P_SYS0014_GET_GROUP_LIST_M', 'P_SYS0014_GET_USER_BY_GROUP_M', 'P_SYS0014_SAVE_GROUP_USER_M') OR PROC_NM IN ('PKG_SYS0014.P_SYS0014_GET_AUTH_LIST_M', 'PKG_SYS0014.P_SYS0014_GET_GROUP_LIST_M', 'PKG_SYS0014.P_SYS0014_GET_USER_BY_GROUP_M', 'PKG_SYS0014.P_SYS0014_SAVE_GROUP_USER_M') GROUP BY UPPER(PROC_NM) ORDER BY 1;

-- [E] 앱계정
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_SYS0014';
SELECT OWNER, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER = 'SCMP_APP' AND SYNONYM_NAME = 'PKG_SYS0014';
